mapper.select:
/* CartSQL.selectCartListCnt */
SELECT COUNT(*)
FROM TB_CART
WHERE MBR_NO = #{mbrNo}

/* CartSQL.selectCartInfo */
SELECT
	A.CART_NO   AS "cartNo",
	A.PRD_CD    AS "prdCd",
	A.ORD_QTY   AS "ordQty"
FROM TB_CART A
WHERE A.CART_NO = #{cartNo}
  AND A.MBR_NO = #{mbrNo}

/* CartSQL.selectCartNo */
SELECT COUNT(*)
FROM TB_CART
WHERE MBR_NO = #{mbrNo}
  AND PRD_CD = #{prdCd}

mapper.insert:
/* CartSQL.insertCart */
INSERT INTO TB_CART (
	MBR_NO, PRD_CD, ORD_QTY, REG_DT, UPD_DT
) VALUES (
	#{mbrNo}, #{prdCd}, #{ordQty}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)

mapper.update:
/* CartSQL.updateCartAddQty */
UPDATE TB_CART
SET ORD_QTY = ORD_QTY + #{ordQty},
	UPD_DT = CURRENT_TIMESTAMP
WHERE MBR_NO = #{mbrNo}
  AND PRD_CD = #{prdCd}

/* CartSQL.updateCartQty */
UPDATE TB_CART
SET ORD_QTY = #{ordQty},
	UPD_DT = CURRENT_TIMESTAMP
WHERE CART_NO = #{cartNo}
  AND MBR_NO = #{mbrNo}

mapper.delete:
/* CartSQL.deleteCart */
DELETE FROM TB_CART
WHERE CART_NO = #{cartNo}
  AND MBR_NO = #{mbrNo}
